(() => { const g=__dmh,P=g.player,V=P.pos.constructor; window.__dmhHold=true; g.godMode=true;
for(let i=0;i<g.zones.length;i++)g.unlockZone(i,true); for(const I of g.interactables)if(I.type==='Door'&&!I.open)g.openDoor(I);
g.phase='Intermission'; g.phaseTimer=1e9;
const top=(x,z)=>{const h=g.phys.raycastDown(new V(x,6000,z),9000,false); return h?h.point.y:-1e9;};
// places to stand: raised spots and plain ground, found by probing around the spawn points
const sp=g.spawnPoints.map(s=>s.pos||s.loc||s), spots=[];
let seed=7; const rnd=()=>{seed=(seed*16807)%2147483647; return seed/2147483647;};
for(let k=0;k<4000&&spots.filter(s=>s.r).length<7;k++){ const s=sp[Math.floor(rnd()*sp.length)], x=s.x+(rnd()-0.5)*2400, z=s.z+(rnd()-0.5)*2400, y=top(x,z); if(y>60&&y<420&&Math.abs(top(x+60,z)-y)<4&&Math.abs(top(x-60,z)-y)<4&&Math.abs(top(x,z+60)-y)<4&&Math.abs(top(x,z-60)-y)<4) spots.push({x,y,z,r:1}); }
for(let k=0;k<5;k++){ const s=sp[Math.floor(rnd()*sp.length)]; spots.push({x:s.x+200,y:top(s.x+200,s.z),z:s.z,r:0}); }
const flags=[], seen=new Set(); let peak=0, peakAlive=0;
const L=g.map.enemies;
for(let si=0; si<spots.length; si++){ const S=spots[si]; P.pos.set(S.x,S.y+114,S.z); P.vel.set(0,0,0);
  for(let t=0;t<16;t++){
    if(t%4===0){ for(let i=0;i<10;i++){ if(g.enemies.filter(e=>!e.dead).length>=44)break; const p=sp[Math.floor(rnd()*sp.length)]; g.spawnEnemy(L[Math.floor(rnd()*L.length)], new V(p.x,p.y+60,p.z), false,-1,1,1,0,false); } }
    window.__dmhHold=false; __sim(30); window.__dmhHold=true; P.pos.set(S.x,S.y+114,S.z); P.vel.set(0,0,0); P.health=P.maxHealth;
    peak=Math.max(peak,g.fx.batches.creature.n); peakAlive=Math.max(peakAlive,g.enemies.length);
    for(const E of g.enemies){ if(E.dead)continue; const f=E.feet(), ty=top(E.pos.x,E.pos.z);
      E._u = ty-f.y>40 ? (E._u||0)+1 : 0; E._e = E.emerge>0 ? (E._e||0)+1 : 0; E._b = E.burrowed ? (E._b||0)+1 : 0; E._lo = f.y < ty-40 ? 1 : 0;
      E._s = (f.y<-25&&!E.burrowed) ? (E._s||0)+1 : 0; const why = E._s>=2?'sunk':E._e>=8?'emerge':E._b>=8?'burrowed':'';
      if(why && !seen.has(E.id+why)){ seen.add(E.id+why); flags.push(why+' '+E.def.name+'/'+E.ai+' @'+Math.round(E.pos.x)+','+Math.round(E.pos.z)+' feet '+Math.round(f.y)+' top '+Math.round(ty)+' h '+Math.round(E.half*2)+' | player '+Math.round(S.x)+','+Math.round(S.y)+','+Math.round(S.z)+(S.r?' raised':'')); }
    }
  }
  for(const E of g.enemies) if(!E.dead && Math.hypot(E.pos.x-S.x,E.pos.z-S.z)<600 && rnd()<0.7) E.takeHit(1e9,E.pos,new V(1,0,0),false);
}
return JSON.stringify({rescues:g.rescues||0, map:g.map.name, peak, peakAlive, n:flags.length, flags:flags.slice(0,40)},null,1); })()
